import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Category = () => {
  const [categories, setCategories] = useState([]);
  const [name, setName] = useState('');
  const [image, setImage] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showForm, setShowForm] = useState(false);
  const role = localStorage.getItem("role");

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchCategories = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/users/allcategories');
      setCategories(response.data);
    } catch (error) {
      console.error("Error fetching categories:", error);
    }
  };

  const handleAddCategory = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append("name", name);
    formData.append("image", image);
    try {
      await axios.post('http://localhost:5000/api/users/addcategory', formData, {
        headers: { "Content-Type": "multipart/form-data" }
      });
      setName('');
      setImage(null);
      setShowForm(false);
      fetchCategories();
    } catch (error) {
      console.error("Error adding category:", error);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.centeredHeader}>
        <h1 style={styles.mainTitle}>Categories</h1>
        <input
          type="text"
          placeholder="Search categories..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={styles.searchInput}
        />
      </div>
      <div style={styles.grid}>
        {categories
          .filter((cat) => cat.name.toLowerCase().includes(searchTerm.toLowerCase()))
          .map((cat) => (
            <div key={cat._id} style={styles.glassCard}>
              <div style={{ ...styles.cardImage, backgroundImage: `url(http://localhost:5000/uploads/${cat.image})` }}>
                <div style={styles.cardOverlay}></div>
                <div style={styles.cardTitleWrap}>
                  <span style={styles.cardTitle}>{cat.name}</span>
                </div>
              </div>
            </div>
          ))}
      </div>
      {role === "admin" && (
        <button style={styles.fab} onClick={() => setShowForm(true)} title="Add Category">
          <span style={styles.fabPlus}>+</span>
        </button>
      )}
      {showForm && (
        <div style={styles.modalOverlay} onClick={() => setShowForm(false)}>
          <div style={styles.modalBox} onClick={e => e.stopPropagation()}>
            <h2 style={styles.formTitle}>Add Category</h2>
            <form onSubmit={handleAddCategory} encType="multipart/form-data" style={styles.form}>
              <input
                type="text"
                placeholder="Enter Category Name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
                style={styles.input}
              />
              <input
                type="file"
                accept="image/*"
                onChange={(e) => setImage(e.target.files[0])}
                required
                style={styles.input}
              />
              <div style={{ display: 'flex', gap: 12, marginTop: 8 }}>
                <button type="submit" style={styles.button}>Add</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowForm(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

const styles = {
  page: {
    minHeight: "100vh",
    background: "linear-gradient(135deg, #181c24 0%, #232a36 100%)",
    fontFamily: "'Segoe UI', sans-serif",
    padding: "0 0 60px 0",
  },
  centeredHeader: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    gap: 18,
    margin: "0 auto 36px auto",
    padding: "48px 0 0 0",
  },
  mainTitle: {
    fontSize: "38px",
    color: "#60a5fa",
    fontWeight: 900,
    margin: 0,
    letterSpacing: 1.2,
    textShadow: "0 2px 12px rgba(96,165,250,0.10)",
  },
  searchInput: {
    background: "rgba(35,42,54,0.85)",
    color: "#e0eafc",
    borderRadius: "30px",
    padding: "14px 28px",
    width: "340px",
    height: "44px",
    border: "1.5px solid #374151",
    fontSize: "17px",
    outline: "none",
    boxShadow: "0 2px 12px rgba(96,165,250,0.10)",
    fontFamily: "inherit",
    marginTop: 18,
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(280px, 1fr))",
    gap: "40px",
    maxWidth: 1100,
    margin: "0 auto",
    padding: "0 16px",
  },
  glassCard: {
    borderRadius: "24px",
    boxShadow: "0 8px 32px rgba(96,165,250,0.18)",
    background: "rgba(35,42,54,0.55)",
    border: "1.5px solid rgba(96,165,250,0.13)",
    overflow: "hidden",
    position: "relative",
    minHeight: 240,
    display: "flex",
    flexDirection: "column",
    justifyContent: "flex-end",
    transition: "transform 0.18s cubic-bezier(.4,2,.6,1), box-shadow 0.18s cubic-bezier(.4,2,.6,1)",
    cursor: "pointer",
    backdropFilter: "blur(6px)",
  },
  cardImage: {
    width: "100%",
    height: 200,
    backgroundSize: "cover",
    backgroundPosition: "center",
    position: "relative",
    display: "flex",
    alignItems: "flex-end",
    justifyContent: "center",
  },
  cardOverlay: {
    position: "absolute",
    left: 0,
    top: 0,
    width: "100%",
    height: "100%",
    background: "linear-gradient(to top, #181c24 70%, rgba(24,28,36,0.0) 100%)",
    opacity: 0.7,
    zIndex: 1,
    borderRadius: "24px",
  },
  cardTitleWrap: {
    position: "absolute",
    left: 0,
    right: 0,
    bottom: 0,
    zIndex: 2,
    padding: "22px 0 18px 0",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "rgba(24,28,36,0.55)",
    borderBottomLeftRadius: "24px",
    borderBottomRightRadius: "24px",
  },
  cardTitle: {
    fontSize: "24px",
    color: "#fff",
    fontWeight: 800,
    letterSpacing: 0.5,
    textShadow: "0 2px 8px rgba(24,28,36,0.18)",
    margin: 0,
  },
  fab: {
    position: "fixed",
    right: 36,
    bottom: 36,
    width: 64,
    height: 64,
    borderRadius: "50%",
    background: "linear-gradient(135deg, #2563eb, #22d3ee)",
    color: "#fff",
    fontSize: 36,
    fontWeight: 900,
    border: "none",
    boxShadow: "0 8px 32px rgba(96,165,250,0.18)",
    cursor: "pointer",
    zIndex: 10001,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    transition: "background 0.2s, box-shadow 0.2s",
  },
  fabPlus: {
    fontSize: 38,
    fontWeight: 900,
    marginTop: -2,
  },
  modalOverlay: {
    position: "fixed",
    left: 0,
    top: 0,
    width: "100vw",
    height: "100vh",
    background: "rgba(24,28,36,0.92)",
    zIndex: 9999,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
  },
  modalBox: {
    background: "#232a36",
    borderRadius: "18px",
    boxShadow: "0 8px 32px rgba(96,165,250,0.18)",
    padding: "36px 32px 28px 32px",
    minWidth: 320,
    maxWidth: 400,
    width: "100%",
    zIndex: 10000,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
  },
  formTitle: {
    fontSize: "22px",
    marginBottom: "20px",
    color: "#60a5fa",
    fontWeight: 700,
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "15px",
    width: "100%",
  },
  input: {
    padding: "12px",
    fontSize: "15px",
    borderRadius: "8px",
    border: "1px solid #374151",
    backgroundColor: "#181c24",
    color: "#e0eafc",
  },
  button: {
    padding: "12px 0",
    background: "linear-gradient(to right, #2563eb, #22d3ee)",
    color: "white",
    fontSize: "16px",
    fontWeight: "bold",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    transition: "opacity 0.3s ease",
    width: 120,
  },
  cancelBtn: {
    padding: "12px 0",
    background: "#374151",
    color: "#e0eafc",
    fontSize: "16px",
    fontWeight: "bold",
    border: "none",
    borderRadius: "8px",
    cursor: "pointer",
    transition: "opacity 0.3s ease",
    width: 120,
  },
};

export default Category;
